"""Generate the event, franchise and system routes with one shared brand shell."""
from pathlib import Path
import re, json
from PIL import Image, ImageOps

ROOT=Path(__file__).resolve().parents[1]
DIST=ROOT/'dist'
page=DIST/'index.html'
home=page.read_text(encoding='utf-8')
original_main=re.search(r'<main\b[\s\S]*?</main>',home).group()

for model in ['mini-go','tech-go']:
    out=DIST/f'assets/official-{model}.webp'
    if not out.exists():
        source=ROOT.parent/f'review/official-machines/{model}.png'
        image=ImageOps.exif_transpose(Image.open(source)).convert('RGB')
        image.thumbnail((900,1300),Image.Resampling.LANCZOS)
        image.save(out,'WEBP',quality=90,method=6)

# Link to dedicated routes rather than the former pending-access dialog.
home=home.replace('<a href="#experiencia">A experiência</a><a href="#drinks">Os drinks</a><a href="#momentos">Seus momentos</a>', '<a href="/" aria-current="page">Home</a><a href="#experiencia">A experiência</a><a href="/franquias/">Franquias</a>')
home=re.sub(r'<button class="nav-systems"[^>]*>[\s\S]*?</button>', '<a class="nav-systems" href="/sistemas/">Acessar os sistemas <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M7 17 17 7M7 7h10v10" stroke="currentColor" stroke-width="1.5"/></svg></a>',home,count=1)
home=re.sub(r'<button class="mobile-systems"[^>]*>[\s\S]*?</button>', '<a class="mobile-systems" href="/sistemas/">Sistemas <span aria-hidden="true">↗</span></a><a href="/franquias/">Seja franqueado <span aria-hidden="true">↗</span></a>',home,count=1)
home=re.sub(r'<button data-open-systems[^>]*>[\s\S]*?</button>', '<a href="/sistemas/">Acessar os sistemas <span aria-hidden="true">↗</span></a>',home)
home=home.replace('href="https://www.quickgodrinks.com.br/sobre" target="_blank" rel="noopener"','href="/franquias/#rede"').replace('href="https://www.quickgodrinks.com.br/#contato" target="_blank" rel="noopener"','href="/franquias/#conversa"')
home=re.sub(r'  <dialog id="systems-dialog"[\s\S]*?</dialog>\n','',home,count=1)
home=home.replace('/app.js?v=dwell-20','/app.js?v=structure-24')
if '/site-pages.css?' not in home:
    home=home.replace('<link rel="stylesheet" href="/footer-section.css?v=network-21">','<link rel="stylesheet" href="/footer-section.css?v=network-21">\n  <link rel="stylesheet" href="/site-pages.css?v=structure-24">')
home=home.replace('https://quickgodrinksbh.com.br/','https://www.quickgodrinks.com.br/')
if '<nav class="mobile-nav" id="mobile-nav" aria-label="Navegação móvel" hidden><a href="/">Home' not in home:
    home=home.replace('<nav class="mobile-nav" id="mobile-nav" aria-label="Navegação móvel" hidden>', '<nav class="mobile-nav" id="mobile-nav" aria-label="Navegação móvel" hidden><a href="/">Home <span>01</span></a>')
# The existing client-side briefing remains the home sales flow. Update its
# review screen's default contact as well as the JS configuration.
whatsapp='https://wa.me/5567991973749?text=Quero%20um%20or%C3%A7amento%20para%20meu%20evento.'
home=home.replace('href="https://quickgoorcamentos.com/">Acessar o canal atual de orçamentos', 'href="'+whatsapp+'">Conversar no WhatsApp')
home=home.replace('href="https://quickgoorcamentos.com/" target="_blank" rel="noopener">Canal de orçamentos','href="'+whatsapp+'" target="_blank" rel="noopener">Continuar no WhatsApp')
home=home.replace('Confira seu pedido e continue pelo canal atual de orçamentos da Quick GO.','Confira seu pedido e continue pelo WhatsApp da Quick GO.')
home=home.replace('Seu resumo fica nesta página. A equipe confirma disponibilidade, valores e reserva pelo atendimento.','Seu resumo fica nesta página até você abrir o WhatsApp e escolher enviar. A equipe confirma disponibilidade, valores e reserva.')
home=home.replace('Ao abrir o canal de orçamentos, você visita o serviço externo da Quick GO.','Ao continuar no WhatsApp, você visita um serviço externo e escolhe quando enviar seu resumo.')
# Preserve the approved hero and drink carousel; replace only the quote area.
quote_template=(ROOT/'scripts/templates/quote-section.html').read_text(encoding='utf-8').strip()
home=re.sub(r'<section class="(?:booking-section section-pad|quote-home)"[^>]*id="orcamento"[\s\S]*?</section>',quote_template,home,count=1)
home=home.replace('/app.js?v=structure-24','/app.js?v=quote-25')
if '/quote-section.css?' not in home:
    home=home.replace('<link rel="stylesheet" href="/site-pages.css?v=structure-24">','<link rel="stylesheet" href="/site-pages.css?v=structure-24">\n  <link rel="stylesheet" href="/quote-section.css?v=quote-25">\n  <script type="module" src="/quote-embed.js?v=quote-25"></script>')
home=home.replace('Monte o pedido nesta página e continue pelo canal de orçamentos. O valor considera data, local, duração, convidados e carta. A data só fica reservada após a confirmação da equipe.', 'Preencha o formulário de orçamento nesta página. A equipe considera data, local, duração, convidados e carta para preparar sua proposta. A data só fica reservada após a confirmação do atendimento.')
home=home.replace('Os dados do pedido são usados apenas no navegador para montar o seu resumo. Nada é enviado automaticamente. Ao continuar no WhatsApp, você visita um serviço externo e escolhe quando enviar seu resumo.', 'O formulário de orçamento é fornecido pelo sistema externo quickgoorcamentos.com. Os dados preenchidos e enviados nele são tratados pelo próprio sistema, conforme as condições apresentadas por ele. Ao usar o atendimento pelo WhatsApp, você visita um serviço externo e decide quando enviar sua mensagem.')
for key in ['inicio','drinks']:
    pattern=r'<section\b[^>]*\bid="'+key+r'"[\s\S]*?</section>'
    assert re.search(pattern,original_main).group()==re.search(pattern,home).group()
page.write_text(home,encoding='utf-8')

footer=re.search(r'<footer class="network-footer"[\s\S]*?</footer>',home).group()
footer=re.sub(r'href="#([^"]+)"',r'href="/#\1"',footer)
privacy='''<dialog id="privacy-dialog" class="privacy-dialog"><button class="dialog-close" data-close aria-label="Fechar privacidade">×</button><p class="eyebrow">PRIVACIDADE</p><h2>Sua privacidade.</h2><p>Os dados do contato de franquias são usados no seu navegador para montar uma mensagem. Nada é enviado automaticamente: você abre o WhatsApp e decide quando enviar.</p><p>Na Home, o formulário de orçamento pertence ao serviço externo quickgoorcamentos.com. Os dados preenchidos nesse formulário são tratados pelo próprio sistema, conforme as condições apresentadas por ele.</p><p>Não instalamos rastreadores de publicidade nesta página. A escolha visual do rodapé não é salva.</p></dialog>'''

def shell(route,title,description,content):
    nav=''.join(f'<a href="{href}"'+(' aria-current="page"' if name==route else '')+f'>{label}</a>' for name,href,label in [('home','/','Home'),('franquias','/franquias/','Franquias'),('sistemas','/sistemas/','Sistemas')])
    return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="theme-color" content="#102f34"><meta name="robots" content="noindex,follow"><title>{title}</title><meta name="description" content="{description}"><link rel="canonical" href="https://quickgo-drinks.vercel.app/{route}/"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:url" content="https://quickgo-drinks.vercel.app/{route}/"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><meta name="twitter:card" content="summary_large_image"><meta property="og:image" content="https://quickgo-drinks.vercel.app/assets/social.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Drink Quick GO com equipamento ao fundo"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/anek-devanagari-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/product-design.css?v=manual-17"><link rel="stylesheet" href="/drinks-carousel.css?v=loop-14"><link rel="stylesheet" href="/brand-typography.css?v=manual-17"><link rel="stylesheet" href="/footer-section.css?v=network-21"><link rel="stylesheet" href="/site-pages.css?v=structure-24"><script type="module" src="/secondary-pages.js?v=structure-24"></script><script type="module" src="/footer-section.js?v=network-21"></script><link rel="stylesheet" href="/quote-section.css?v=quote-25"></head>
<body class="site-secondary"><a class="skip-link" href="#conteudo">Ir para o conteúdo</a><header class="header" id="header"><a class="brand" href="/" aria-label="Quick GO, início"><img src="/assets/logo.webp" width="190" height="39" alt="Quick GO"></a><nav class="desktop-nav" aria-label="Navegação principal">{nav}</nav><div class="header-actions"><a class="nav-cta" href="/#orcamento">Orçamento do bar <span aria-hidden="true">↗</span></a><button class="menu-toggle" aria-label="Abrir menu" aria-expanded="false" aria-controls="mobile-nav"><span></span><span></span></button></div></header><nav class="mobile-nav" id="mobile-nav" aria-label="Navegação móvel" hidden>{nav}<a href="/#orcamento">Contratar o bar <span aria-hidden="true">↗</span></a></nav><main id="conteudo">{content}</main>{footer}{privacy}<a class="mobile-booking" href="{'#conversa' if route=='franquias' else '/#orcamento'}">{'Quero ser franqueado' if route=='franquias' else 'Orçamento para meu evento'} <span aria-hidden="true">↗</span></a></body></html>'''

franchise='''<section class="franchise-hero"><div class="container franchise-hero-grid"><div class="franchise-hero-copy"><p class="eyebrow">FRANQUIAS QUICK GO</p><h1>O próximo brinde.<br>O seu próximo<br>negócio.</h1><p>Máquinas de preparo automático, receitas padronizadas e o suporte de uma rede para empreender com drinks.</p><a class="button button-light" href="#conversa">Quero conhecer a franquia <span aria-hidden="true">↗</span></a><small>Para empresários, empresas e quem quer começar uma operação com a Quick GO.</small></div><figure class="franchise-product"><img src="/assets/official-mini-go.webp" width="859" height="1300" alt="Equipamento Mini GO da Quick GO, com tela frontal e compartimento para o copo"><figcaption>MINI GO · TECNOLOGIA PARA SERVIR</figcaption></figure></div></section>
<div class="franchise-principles"><div class="container"><span>PREPARO AUTOMÁTICO</span><span>RECEITAS PADRONIZADAS</span><span>MODELOS DE EQUIPAMENTOS</span><span>SUPORTE DA REDE</span></div></div>
<section class="franchise-section" id="rede"><div class="container franchise-network"><img class="franchise-network-photo" src="/assets/story-touch.webp" width="1100" height="1300" alt="Convidada usando a tela de uma máquina Quick GO em um evento" loading="lazy"><div class="franchise-network-copy"><p class="eyebrow">UMA REDE. DIFERENTES POSSIBILIDADES.</p><h2>Coquetelaria<br>com tecnologia.<br>Um negócio com marca.</h2><p>A Quick GO é uma rede de microfranquias que combina máquinas automáticas e uma experiência de coquetelaria. A proposta une praticidade na operação e consistência no preparo.</p><div class="franchise-network-facts"><div><h3>Em eventos</h3><p>Casamentos, celebrações, ações de marca e encontros corporativos.</p></div><div><h3>Em empresas</h3><p>Possibilidades para bares, restaurantes, hotéis e outros estabelecimentos, conforme o modelo da operação.</p></div></div></div></div></section>
<section class="franchise-section franchise-models" id="equipamentos"><div class="container"><div class="franchise-section-heading"><div><p class="eyebrow">OS EQUIPAMENTOS</p><h2>Escolha o formato.<br>Planeje a operação.</h2></div><p>Conheça os modelos apresentados pela Quick GO e converse com a equipe sobre a aplicação no seu negócio.</p></div><div class="franchise-model-grid"><article class="franchise-model"><img src="/assets/official-mini-go.webp" width="859" height="1300" alt="Máquina Mini GO da Quick GO" loading="lazy"><div><p class="eyebrow">COMPACTA</p><h3>Mini GO</h3><p>O formato compacto da rede, apresentado para operações e espaços menores.</p><a class="underlined-link" href="#conversa" data-franchise-model="Mini GO">Tenho interesse <span aria-hidden="true">↗</span></a></div></article><article class="franchise-model"><img src="/assets/official-tech-go.webp" width="382" height="998" alt="Máquina Tech GO com iluminação azul e estrutura de piso" loading="lazy"><div><p class="eyebrow">CAPACIDADE EXPANDIDA</p><h3>Tech GO</h3><p>O modelo apresentado pela rede para operações que buscam mais capacidade e recursos.</p><a class="underlined-link" href="#conversa" data-franchise-model="Tech GO">Tenho interesse <span aria-hidden="true">↗</span></a></div></article></div><p class="franchise-fineprint">Configuração, disponibilidade, capacidade, insumos, investimento e condições de fornecimento são confirmados pela equipe na apresentação comercial.</p></div></section>
<section class="franchise-section franchise-support"><div class="container"><div class="franchise-section-heading"><div><p class="eyebrow">ALÉM DA MÁQUINA</p><h2>Uma operação<br>com apoio da rede.</h2></div><p>Conheça a estrutura de suporte apresentada pela Quick GO para seus franqueados.</p></div><div class="franchise-support-grid"><article><span>01</span><h3>Treinamento<br>e início</h3><p>Orientação para conhecer o equipamento, as receitas e a rotina da operação.</p></article><article><span>02</span><h3>Marca<br>e marketing</h3><p>Identidade e materiais da Quick GO para apoiar a comunicação do negócio.</p></article><article><span>03</span><h3>Assistência<br>técnica</h3><p>Converse com a rede sobre o suporte ao equipamento e suas condições de atendimento.</p></article><article><span>04</span><h3>Acompanhamento<br>da operação</h3><p>Alinhamento do modelo de atuação e dos próximos passos com a equipe da marca.</p></article></div></div></section>
<section class="franchise-section franchise-enquiry" id="conversa"><div class="container"><div class="franchise-enquiry-grid"><div class="franchise-enquiry-copy"><p class="eyebrow">VAMOS CONVERSAR SOBRE NEGÓCIO</p><h2>Leve a Quick GO<br>para o seu<br>próximo passo.</h2><p>Conte de onde você é e qual equipamento chamou sua atenção. A equipe apresenta o modelo de franquia, investimento, fornecimento e condições para operar.</p><ol><li><span>01</span>Apresente seu interesse e sua cidade.</li><li><span>02</span>Conheça equipamentos e condições.</li><li><span>03</span>Avalie a proposta com a equipe.</li></ol></div><div><form class="franchise-form" id="franchise-form"><label>Seu nome<input name="name" autocomplete="name" maxlength="150" required></label><label>Cidade e UF<input name="city" autocomplete="address-level2" placeholder="Ex.: Campo Grande / MS" maxlength="150" required></label><label class="wide">Empresa (opcional)<input name="company" autocomplete="organization" maxlength="200"></label><label class="wide" for="franchise-model">Qual modelo quer conhecer?<select id="franchise-model" name="model"><option>Quero orientação sobre os modelos</option><option>Mini GO</option><option>Tech GO</option></select></label><p class="form-error" id="franchise-error" role="status" aria-live="polite"></p><button class="button button-dark" type="submit">Preparar contato de franquia <span aria-hidden="true">↗</span></button><p class="form-note">Você revisa a mensagem e continua no WhatsApp. Seus dados não são enviados automaticamente.</p></form><div id="franchise-result" class="franchise-result" tabindex="-1" role="region" aria-label="Contato de franquia preparado" hidden><h3>Vamos falar de franquia.</h3><pre id="franchise-summary"></pre><a id="franchise-whatsapp" class="button button-light" href="https://wa.me/5567991973749" target="_blank" rel="noopener">Continuar no WhatsApp <span aria-hidden="true">↗</span></a><p>A equipe confirma investimento, disponibilidade e condições. A preparação desta mensagem não constitui compra ou contratação.</p></div></div></div><div class="franchise-other-route"><p>Quer contratar o bar para uma festa, sem operar uma franquia?</p><a class="underlined-link" href="/#orcamento">Pedir orçamento do serviço <span aria-hidden="true">↗</span></a></div></div></section>'''
systems='''<section class="systems-intro-section"><div class="container systems-intro-grid"><div><p class="eyebrow">QUICK GO · SISTEMAS</p><h1>A central<br>dos franqueados.</h1><p>Um espaço para os acessos e ferramentas da rede Quick GO.</p></div><a class="underlined-link" href="/#orcamento">Quero contratar o bar <span aria-hidden="true">↗</span></a></div></section><section class="systems-pending" aria-labelledby="system-title"><div class="container"><div class="systems-pending-panel"><span class="systems-pending-icon" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none"><rect x="6" y="14" width="20" height="14" rx="3" stroke="currentColor" stroke-width="1.4"/><path d="M10 14V9a6 6 0 0 1 12 0v5M16 19v4" stroke="currentColor" stroke-width="1.4"/></svg></span><p class="eyebrow">ACESSO DA REDE</p><h2 id="system-title">Estamos preparando<br>seu acesso.</h2><p>A área dos franqueados está em preparação. Os acessos serão disponibilizados aqui quando o sistema estiver pronto.</p><a class="button button-dark" href="/#orcamento">Orçamento para meu evento <span aria-hidden="true">↗</span></a><a class="underlined-link" href="/franquias/">Quero conhecer a franquia <span aria-hidden="true">↗</span></a></div></div></section>'''

for route,content,title,description in [('franquias',franchise,'Franquias Quick GO · Equipamentos e oportunidades de negócio','Conheça a franquia Quick GO, os equipamentos Mini GO e Tech GO e as condições para empreender com a rede.'),('sistemas',systems,'Sistemas Quick GO · Central dos franqueados','A central dos franqueados Quick GO está em preparação. Acompanhe a disponibilização dos acessos da rede.')]:
    directory=DIST/route;directory.mkdir(exist_ok=True)
    (directory/'index.html').write_text(shell(route,title,description,content),encoding='utf-8')
print('Home, Franquias and Sistemas generated.')
